                tt,bb,LL,R_=wtop(r0,c0,c1),wbot(r1,c0,c1),lft(r0,r1,c0),rgt(r0,r1,c1)
                if tt is None or bb is None or LL is None or R_ is None: continue
                hh=bb-tt+1; ww=R_-LL+1
                s=max(hh,ww)
                col=m.get(s,{})
                if col is None:
                    ks=sorted(m); hi=max([k for k in ks if k<s],default=None); lo=min([k for k in ks if k>s],default=None)
                    if hi is not None and lo is not None:
                        d=(m[lo]-m[hi])/float(lo-hi); col=round(m[hi]+d*(s-hi))
                    elif hi is not None: col=m[hi]
                    else: continue
                for a,b in cells: out[a][b]=col
    return out
